local function root_has(patterns, opts)
  opts = opts or {}
  local found = vim.fs.find(patterns, {
    path = opts.path or vim.fn.getcwd(),
    upward = true,
    stop = vim.env.HOME,
  })
  return found[1]
end

local function is_viteplus_project(ctx)
  local path = ctx and ctx.dirname or vim.fn.getcwd()

  if root_has({ "vite.config.ts", "vite.config.mts", "vite.config.js" }, { path = path }) then
    local config = root_has({ "vite.config.ts", "vite.config.mts", "vite.config.js" }, { path = path })
    if config and vim.fn.filereadable(config) == 1 then
      local lines = table.concat(vim.fn.readfile(config, "", 80), "\n")
      if lines:find("vite%-plus") then
        return true
      end
    end
  end

  local pkg = root_has({ "package.json" }, { path = path })
  if pkg and vim.fn.filereadable(pkg) == 1 then
    local lines = table.concat(vim.fn.readfile(pkg), "\n")
    return lines:find('"vite%-plus"') or lines:find('"@voidzero%-dev/vite%-plus')
  end

  return false
end

local function command_exists(cmd)
  return vim.fn.executable(cmd) == 1
end

