        append_fname = false,
        args = { "lint", "--format", "json" },
        ignore_exitcode = true,
        parser = function(output)
          if output == "" then
            return {}
          end

          local ok, decoded = pcall(vim.json.decode, output)
          if not ok or type(decoded) ~= "table" then
            return {}
          end

          local diagnostics = {}

          local items = decoded.diagnostics or decoded
          if type(items) ~= "table" then
            return diagnostics
          end

          for _, item in ipairs(items) do
            local filename = item.filename or item.file or item.path
            local range = item.range or item.location or {}
            local start = range.start or item.start or {}

            table.insert(diagnostics, {
              filename = filename,
              lnum = math.max((start.line or item.line or 1) - 1, 0),
              col = math.max((start.column or item.column or 1) - 1, 0),
              severity = vim.diagnostic.severity.WARN,
              source = "vp lint",
              message = item.message or item.msg or "Vite+ lint diagnostic",
